O.mkdir(exist_ok=True)
D=decimal.Decimal
def load(p):return json.loads(p.read_text())
def save(n,data):
 if isinstance(data,list) and data:
  keys=list(dict.fromkeys(k for x in data for k in x))
  data=[{k:x.get(k)for k in keys}for x in data]
 (O/(n+'.json')).write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
 if isinstance(data,list) and data:
  with (O/(n+'.csv')).open('w',newline='') as f:
   w=csv.DictWriter(f,fieldnames=list(data[0]));w.writeheader()
   for x in data:w.writerow({k:json.dumps(v,ensure_ascii=False,separators=(',',':')) if isinstance(v,(dict,list,bool)) or v is None else v for k,v in x.items()})
rows=load(I/'CN_AUDIT_40.json');original_gate=load(I/'RELEASE_GATE.json')
