 category.append({'category_id':c['id'],'category_name':c['name'],'volume_tonnes':float(kg/1000)if rr else None,'trade_value_eur':float(eur)if rr else None,'cn_count':len(rr),'cn_codes':[x['cn8']for x in rr],'linked_cn_market_entities':len(rr),'linked_existing_direct_commercial_entities':len(commercial),'linked_existing_scope_candidate_entities':len(candidate_ids),'directly_supported_full_scope_species':len(direct_species),'limited_scope_species':len(partial_species-direct_species),'core_volume_share_percent':round(float(kg/total_kg*100),6)if rr else None,'core_value_share_percent':round(float(eur/total_eur*100),6)if rr else None,'state':'MEASURED_CN_CATEGORY_TOTAL' if rr else 'DATA_GAP','allocation':'No constituent species volumes or counts of actual contributors inferred.'})
